/* FreeDME design-only simulator. Never deploy as the production exchange. PRS v0.9. */
'use strict';
const CATS=['Walkers','Canes','Shower chairs','Commodes','Crutches','Manual wheelchairs','Other'];
const PEOPLE={recipient:{name:'Maya',role:'Recipient / caregiver'},donor:{name:'Jordan',role:'Donor'},moderator:{name:'Alex',role:'Moderator'}};
const SEED=()=>({version:1,role:'visitor',signed:false,time:Date.parse('2026-10-16T17:00:00Z'),sms:true,evidence:'none',consent:false,loans:true,requests:[],cases:[{id:'C-100',item:7,reason:'Suspected recall',detail:'Fictional review scenario: model label needs clarification.',state:'open',owner:'Alex',severity:'standard'}],events:[],items:[
{id:1,title:'Folding walker',cat:'Walkers',city:'Oakland',miles:2,kind:'gift',status:'available',owner:'Jordan',condition:'Gently used',model:'Sample W-100',desc:'Lightweight folding frame with two front wheels. Folds flat for collection.',clean:'Cleaned by donor',defects:'Small cosmetic scratches; no known missing parts.',max:0},
{id:2,title:'Adjustable walking cane',cat:'Canes',city:'Berkeley',miles:5,kind:'gift',status:'available',owner:'Jordan',condition:'Good',model:'Sample C-20',desc:'Adjustable single-point cane with a comfortable grip. Please confirm height and fit with a qualified professional.',clean:'Cleaned by donor',defects:'Light wear on handle; tip reported intact.',max:0},
{id:3,title:'Manual wheelchair',cat:'Manual wheelchairs',city:'Walnut Creek',miles:18,kind:'loan',status:'available',owner:'Jordan',condition:'Gently used',model:'Sample M-18',desc:'Folding manual wheelchair for a temporary need. Configuration is a design example pending DEC02 approval.',clean:'Cleaned by donor',defects:'No known defects reported. Not inspected by FreeDME.',max:14,loanUntil:'2026-10-30'},
{id:4,title:'Shower chair with back',cat:'Shower chairs',city:'Richmond',miles:10,kind:'gift',status:'available',owner:'Jordan',condition:'Good',model:'Sample S-4',desc:'Freestanding shower chair with backrest. Check dimensions, stability and manufacturer instructions before use.',clean:'Cleaned by donor',defects:'Minor marks on seat; feet reported intact.',max:0},
{id:5,title:'Bedside commode',cat:'Commodes',city:'Concord',miles:24,kind:'gift',status:'available',owner:'Jordan',condition:'Good',model:'Sample B-6',desc:'Freestanding bedside commode. Review cleaning, condition and fit before deciding whether it meets your needs.',clean:'Cleaned by donor',defects:'No missing parts reported.',max:0},
{id:6,title:'Adjustable crutches',cat:'Crutches',city:'Oakland',miles:3,kind:'loan',status:'available',owner:'Jordan',condition:'Good',model:'Sample CR-2',desc:'Pair of adjustable crutches. Appropriate fitting and safe use guidance should come from a qualified professional.',clean:'Cleaned by donor',defects:'Light cosmetic wear.',max:7,loanUntil:'2026-10-23'},
{id:7,title:'Walker awaiting review',cat:'Walkers',city:'Berkeley',miles:6,kind:'gift',status:'pending_review',owner:'Jordan',condition:'Condition uncertain',model:'Unknown',desc:'Fictional submission for moderator review. Label is unreadable.',clean:'Unknown',defects:'Wheel condition needs clarification.',max:0,hold:true}
]});
let S=SEED();
const active=r=>['pending','offered','reserved','loaned'].includes(r.state);
const item=id=>S.items.find(x=>x.id===+id);
const request=id=>S.requests.find(x=>x.id===id);
const allocation=id=>S.requests.find(r=>r.item===+id&&active(r));
const event=(text)=>S.events.unshift({at:S.time,text});
const save=()=>{try{if(typeof localStorage!=='undefined')localStorage.setItem('freedme-review-v09',JSON.stringify(S));}catch(_){/* Continue in memory when browser storage is unavailable. */}};
function queueHandoffFollowups(){for(const r of S.requests){if(r.state!=='reserved'||r.handoff||!Number.isFinite(r.reserved)||S.time<r.reserved+7*86400000)continue;if(S.cases.some(c=>c.kind==='handoff_followup'&&c.requestId===r.id))continue;const c={id:'C-'+(S.cases.length+101),kind:'handoff_followup',requestId:r.id,item:r.item,reason:'Check unconfirmed handoff',detail:'Contact both donor Jordan and recipient Maya to check whether the actual handoff occurred. Record each response and the outcome. Do not assume equipment was transferred because a week has passed.',state:'open',owner:'Alex',severity:'standard',created:S.time,due:r.reserved+7*86400000};S.cases.push(c);event(c.id+': seven-day handoff follow-up queued for '+r.id+'.');}}
function followupContext(c){if(c.kind!=='handoff_followup')return '';const r=request(c.requestId);return `<div class="note"><b>Reservation ${e(c.requestId)}</b><p>Reserved: ${r?date(r.reserved):'Unavailable'}<br>Follow-up due: ${date(c.due)}</p><p>Current status: ${r?e(status(r.state)):'Request unavailable'}. ${r?.handoff?'Handoff has since been confirmed by '+e(r.handoffBy||'donor')+'. Review the update before contacting participants.':r?.state==='reserved'?'Physical handoff remains unconfirmed. Contact both participants.':'This reservation is no longer active. Review its history before contacting participants.'}</p><ol><li>Contact donor Jordan and record whether equipment was handed over.</li><li>Contact recipient Maya and record whether equipment was received.</li><li>Record both responses, any conflicting information, and the next step in the closure reason. Keep the task open if follow-up is still needed.</li></ol><p>Sample participants only. No real calls or messages are sent.</p></div>`;}
function expire(){S.requests.forEach(r=>{if((r.state==='pending'&&S.time>=r.created+48*3600000)||(r.state==='offered'&&S.time>=r.offered+24*3600000)){r.expiredFrom=r.state;r.state='expired';item(r.item).status='unavailable';event('Request '+r.id+' expired; owner availability confirmation required.');}else if(r.state==='pending'&&S.time>=r.created+24*3600000&&!r.reminded){r.reminded=true;event('24-hour pending reminder recorded'+(S.sms?' (simulated SMS).':' as account notice only; routine SMS is off.'));}});queueHandoffFollowups();save();}
function createRequest(id,{loanDays,caregiver=false,consent=false,evidenceDocument}={}){expire();const i=item(id);if(!S.signed||S.role!=='recipient')throw Error('Use the recipient sample account first.');if(!i||i.status!=='available'||i.hold||allocation(id))throw Error('This item is no longer available.');if(!['utility','license'].includes(evidenceDocument)||S.evidence!=='reviewed'||!consent)throw Error('Complete identity/address evidence review and consent before requesting either a gift or loan.');if(i.kind==='loan'){if(!S.loans)throw Error('Loan preview is disabled.');if(i.loanUntil)i.max=loanDaysUntil(i.loanUntil);if(S.evidence!=='reviewed'||!consent)throw Error('Sample evidence review and separate consent are required.');if(!Number.isInteger(+loanDays)||+loanDays<1||+loanDays>i.max)throw Error('Choose a whole-day period between 1 and '+i.max+'.');}const r={id:'R-'+(S.requests.length+101),item:i.id,state:'pending',created:S.time,caregiver,consent,identityEvidence:{firstName:'Maya',lastName:'Example',address:'100 Example Lane, Sample City',zip:'00000 (sample only)',status:'sample-reviewed',reviewedAt:S.time,subject:caregiver?'caregiver':'recipient'},loanDays:+loanDays||null,evidenceVersion:S.evidence,history:['Request submitted']};S.requests.push(r);S.requests.forEach(previous=>{if(previous.id!==r.id&&previous.item===i.id&&previous.state==='expired'){previous.hiddenForRecipient=true;previous.replacedBy=r.id;}});event('Maya requested '+i.title+'. One request holds this item.');save();return r;}
function move(id,action){expire();const r=request(id);if(!r)throw Error('Request not found.');const i=item(r.item);const donor=['offer','decline','unavailable','return'].includes(action);if(!S.signed||(action==='handoff'?!['donor','recipient'].includes(S.role):S.role!==(donor?'donor':'recipient')))throw Error('Switch to the correct signed-in sample role.');if(['offer','accept'].includes(action)&&(i.hold||r.paused))throw Error('Resolve the safety or messaging hold before progressing.');if(['offer','accept'].includes(action)&&i.kind==='loan'&&(!r.consent||S.evidence!=='reviewed'))throw Error('Loan evidence or consent is no longer valid. New consent is required.');if(action==='offer'&&r.state==='pending'){r.state='offered';r.offered=S.time;}else if(action==='decline'&&r.state==='pending'){r.state='declined';i.status='available';}else if(action==='unavailable'&&['pending','offered'].includes(r.state)){r.state='closed_unavailable';i.status='unavailable';}else if(action==='accept'&&r.state==='offered'){r.state='reserved';r.reserved=S.time;i.status='reserved';}else if(action==='cancel'&&['pending','offered','reserved'].includes(r.state)){r.state='cancelled';i.status='unavailable';}else if(action==='handoff'&&r.state==='reserved'){r.handoff=S.time;r.handoffBy=S.role;r.state=i.kind==='loan'?'loaned':'completed';i.status=i.kind==='loan'?'loaned':'donated';}else if(action==='return'&&r.state==='loaned'){r.returned=S.time;r.state='completed';i.status='unavailable';}else throw Error('This action is not available in the current state.');r.history.push(action+(action==='handoff'?' confirmed by '+PEOPLE[S.role].name+' ('+S.role+')':'')+' · '+new Date(S.time).toLocaleString());event(r.id+': '+action+(action==='handoff'?' confirmed by '+PEOPLE[S.role].name+' ('+S.role+')':'')+'. Physical outcomes recorded separately.');save();}
function validateHandoff(values,required=false){
 const day=String(values.day||'').trim(),time=String(values.time||'').trim(),place=String(values.place||'').trim();
 const any=!!(day||time||place);
 if(any){
  if(!day||!time||!place)throw Error('Enter a day, time and public meeting location, or leave all three blank.');
  const parsed=new Date(day+'T12:00:00Z');
  if(!/^\d{4}-\d{2}-\d{2}$/.test(day)||Number.isNaN(parsed.getTime())||parsed.toISOString().slice(0,10)!==day||!/^([01]\d|2[0-3]):[0-5]\d$/.test(time))throw Error('Enter a valid meeting day and time.');
  const nowTime=new Intl.DateTimeFormat('en-GB',{timeZone:'America/Los_Angeles',hour:'2-digit',minute:'2-digit',hourCycle:'h23'}).format(new Date(S.time));
  if(day+'T'+time<=loanToday()+'T'+nowTime)throw Error('Choose a future meeting day and time (Pacific Time).');
  if(place.length>200)throw Error('Keep the meeting location within 200 characters.');
 }
 if(required&&!any)throw Error('Enter a day, time and public meeting location.');
 return any?{day,time,place}:null;
}
function approveWithSuggestion(id,values={}){
 const proposal=validateHandoff(values),any=!!proposal;
 move(id,'offer');
 const r=request(id);
 r.handoffSuggestion=any?{...proposal,timeZone:'America/Los_Angeles',suggestedAt:S.time,proposedBy:'donor',revision:1}:null;
 r.approvalSms=any?'Your request is approved. The donor has suggested a handoff location and time. Open My Activity on FreeDME to review the suggestion and accept the offer.':'Your request is approved. Open My Activity on FreeDME to review and accept the offer.';
 r.approvalNotification=S.sms?'Simulated SMS notification — not sent':'SMS suppressed: routine texts off';
 r.history.push(any?'Donor suggested a handoff day, time and public location.':'Approved without a handoff suggestion.');
 event(r.id+': '+r.approvalNotification);save();return r;
}
function approveDialog(id){
 const r=request(id),i=r&&item(r.item);
 if(!S.signed||S.role!=='donor'||!r||r.state!=='pending')throw Error('A pending request and donor sign-in are required.');
 modal(`<h2>Approve request</h2><p>${e(i.title)}</p><p>Optionally suggest a handoff day, time and public location. The recipient still needs to accept your offer and agree on the arrangements.</p><form id="approve-request" data-id="${e(id)}"><label>Suggested day<input type="date" name="day" min="${loanToday()}"></label><label>Suggested time (Pacific Time)<input type="time" name="time"></label><label>Suggested public meeting location<input name="place" maxlength="200" placeholder="For example, the library main entrance"></label><p class="muted">Choose a public, nonresidential place in daylight while it is open. Suggestions appear only in this exchange; no location or time is included in the SMS preview.</p><p role="alert" class="error-text"></p><button class="primary">Approve</button></form>`);
}
function handoffContext(id,revision){
 expire();const r=request(id),i=r&&item(r.item);
 if(!S.signed||!['donor','recipient'].includes(S.role)||!r||!['offered','reserved'].includes(r.state)||r.paused||i.hold)throw Error('This exchange is not available for handoff arrangements.');
 if(i.kind==='loan'&&(!r.consent||S.evidence!=='reviewed'))throw Error('Current loan consent and reviewed evidence are required.');
 if(Number(revision)!==(r.handoffSuggestion?.revision||1))throw Error('The suggestion has changed. Refresh and review the latest details.');
 return r;
}
function updateHandoff(id,revision,values,confirm=false){
 const r=handoffContext(id,revision),x=r.handoffSuggestion;
 if(confirm){
  if(!x||x.confirmedAt||(x.proposedBy||'donor')===S.role)throw Error('Only the other participant can accept a pending suggestion.');
  validateHandoff(x,true);
 }else{
  values=validateHandoff(values,true);
  if(x&&['day','time','place'].every(k=>x[k]===values[k]))throw Error('Change the day, time or location before submitting.');
 }
 r.handoffHistory=r.handoffHistory||[];
 if(x)r.handoffHistory.push({...x});
 r.handoffSuggestion=confirm?{...x,confirmedAt:S.time,confirmedBy:S.role,revision:(x.revision||1)+1}:{...values,timeZone:'America/Los_Angeles',suggestedAt:S.time,proposedBy:S.role,revision:(x?.revision||1)+1};
 const audience=S.role==='recipient'?'donor':'recipient';
 const text=confirm?'The '+S.role+' has accepted the suggested handoff day, time and location. Open My Activity on FreeDME to review the arrangements.':'The '+S.role+' has suggested a handoff day, time and location. Open My Activity on FreeDME to review and confirm or suggest changes.';
 r.handoffNotifications=r.handoffNotifications||[];
 r.handoffNotifications.push({to:audience,text,at:S.time,status:S.sms?'Simulated SMS notification — not sent':'SMS suppressed: routine texts off'});
 r.history.push(S.role+(confirm?' accepted handoff arrangements.':' proposed handoff arrangements.'));
 event(r.id+': '+r.history.at(-1));save();return r;
}
function handoffDialog(token){
 const [id,revision]=token.split(':');const r=handoffContext(id,revision),x=r.handoffSuggestion||{};
 modal(`<h2>Suggest handoff arrangements</h2><p>${e(item(r.item).title)}</p><form id="handoff-proposal" data-id="${e(id)}" data-revision="${e(revision)}"><label>Suggested day<input type="date" name="day" min="${loanToday()}" value="${e(x.day)}" required></label><label>Suggested time (Pacific Time)<input type="time" name="time" value="${e(x.time)}" required></label><label>Suggested public meeting location<input name="place" maxlength="200" value="${e(x.place)}" required></label><p>Choose a public, nonresidential place in daylight while it is open. The other participant must accept any changes. SMS previews contain no meeting details.</p><p role="alert" class="error-text"></p><button class="primary">Send suggestion</button></form>`);
}
function handoffSuggestionView(r,i){
 if(!S.signed||!['donor','recipient'].includes(S.role)||!['offered','reserved'].includes(r.state)||r.paused||i.hold)return '';
 const x=r.handoffSuggestion,token=r.id+':'+(x?.revision||1),other=x&&(x.proposedBy||'donor')!==S.role;
 return `<section class="note" aria-label="Suggested handoff"><h3>${x?.confirmedAt?'Agreed handoff arrangements':x?(x.proposedBy==='recipient'?'Recipient’s':'Donor’s')+' suggested handoff':'Handoff arrangements'}</h3>${x?`<p><b>Day:</b> ${e(new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(new Date(x.day+'T12:00:00Z')))}<br><b>Time:</b> ${e(x.time)} Pacific Time<br><b>Location:</b> ${e(x.place)}</p>`:'<p>No handoff arrangements suggested yet.</p>'}<p>${x?.confirmedAt?'Both participants have agreed to these arrangements. Physical handoff is not yet confirmed.':other?'Review and accept these arrangements or suggest changes.':'Waiting for the other participant to accept your suggestion.'}${r.state==='offered'?' The recipient must also accept the equipment offer to reserve the item.':''}</p><div class="actions">${other&&!x.confirmedAt?btn(S.role==='recipient'?'Accept suggested handoff':'Confirm suggested handoff','handoff-agree',token,'primary'):''}${btn(x?'Suggest a different day/time or location':'Suggest day/time and location','handoff-propose',token)}</div></section>${r.handoffNotifications?.length?`<details><summary>Handoff SMS previews</summary>${r.handoffNotifications.map(n=>`<p><b>To ${e(n.to)}:</b> ${e(n.status)}<br>${e(n.text)}</p>`).join('')}</details>`:''}${r.approvalSms?`<details><summary>Approval SMS preview</summary><p>${e(r.approvalNotification)}</p><p>${e(r.approvalSms)}</p></details>`:''}`;
}
function revokeConsent(id){const r=request(id);if(!S.signed||S.role!=='recipient')throw Error('Recipient access required.');if(!r||item(r.item)?.kind!=='loan'||!r.consent)throw Error('No active loan disclosure consent to revoke.');if(r.handoff||!['pending','offered','reserved'].includes(r.state))throw Error('Consent cannot be revoked after the equipment has been loaned.');r.consent=false;event('Consent revoked for '+id);save();}
function reopen(id,confirmed){const i=item(id);if(S.role!=='donor'||!S.signed||!confirmed)throw Error('Owner possession and availability confirmation is required.');if(i.hold)throw Error('A safety hold prevents reopening.');if(!['unavailable','donated','withdrawn'].includes(i.status))throw Error('This item is not eligible to reopen.');const r=allocation(id);if(r){r.state='closed_unavailable';r.history.push('Owner ended prior allocation');}i.status='available';i.generation=(i.generation||0)+1;event(i.title+' reopened by owner; previous action links invalidated.');save();}
function report(id,reason,detail){const c={id:'C-'+(S.cases.length+101),item:+id,reason,detail,state:'open',owner:'Alex',severity:reason==='Unsafe equipment'?'urgent':'standard'};S.cases.push(c);event(c.id+' submitted to restricted moderator queue.');save();return c;}
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pic=(i,v=0)=>i.cat==='Other'?'data:image/svg+xml,'+encodeURIComponent('<svg xmlns="http://www.w3.org/2000/svg" width="640" height="480" viewBox="0 0 640 480"><rect width="640" height="480" fill="#edf4f2"/><rect x="220" y="120" width="200" height="180" rx="18" fill="none" stroke="#167b78" stroke-width="8"/><path d="M280 210h80m-40-40v80" stroke="#167b78" stroke-width="8"/><text x="320" y="355" text-anchor="middle" font-family="sans-serif" font-size="24" fill="#193c55">Other equipment · Sample image</text></svg>'):'assets/'+CATS.indexOf(i.cat)+(['','-upper','-base'][v])+'.svg';
const VIEW_NAMES=['Full view','Upper detail','Base detail'];
const status=s=>s.replaceAll('_',' ').replace(/^./,x=>x.toUpperCase());
function loanDateLabel(i){if(!i.loanUntil)return 'Date not specified';const d=new Date(i.loanUntil+'T12:00:00Z');return Number.isNaN(d.getTime())?'Date not specified':new Intl.DateTimeFormat('en-US',{month:'short',day:'numeric',year:'numeric',timeZone:'UTC'}).format(d);}
const badge=i=>`<span class="badge ${i.kind==='loan'?'loan':''}">${i.kind==='loan'?'FREE LOAN: UNTIL '+e(loanDateLabel(i)):'Free to keep'}</span>`;
const btn=(text,action,id='',cls='')=>`<button class="${cls}" data-action="${action}" data-id="${e(id)}">${text}</button>`;
const link=(text,path,cls='')=>`<a class="${cls}" href="#${path}">${text}</a>`;
const check=(name,text,required=true)=>`<label class="check"><input type="checkbox" name="${name}" ${required?'required':''}> <span>${text}</span></label>`;
const guidance=`<div class="note"><b>Meet safely, together.</b><br>Arrange pickup or return in a public, nonresidential place, in daylight while the venue is open. FreeDME does not inspect equipment, arrange transport or guarantee returns. Decline an item that seems unsafe or unsuitable.</div>`;
function card(i){return `<article class="card" data-gallery="${i.id}"><div class="image">${badge(i)}<img class="gallery-main" src="${pic(i)}" alt="${e(i.title)} — full view, sample illustration"></div><div class="gallery-thumbs" role="group" aria-label="Sample images of ${e(i.title)}">${VIEW_NAMES.map((name,v)=>`<button class="gallery-thumb" data-action="photo" data-id="${i.id}:${v}" aria-label="${e(i.title)}: ${name}" aria-pressed="${v===0}"><img src="${pic(i,v)}" alt="" loading="lazy"><span>${name}</span></button>`).join('')}</div><p class="gallery-caption">3 illustrated sample views · Not actual item photos</p><div class="card-body"><h3>${e(i.title)}</h3><p class="muted">${e(i.condition)} · Donor reported</p><div class="meta"><span>⌖ ${e(i.city)}</span></div>${btn('View equipment →','detail',i.id)}</div></article>`;}
function showPhoto(key){const [id,view]=key.split(':').map(Number);const i=item(id);if(!i||!VIEW_NAMES[view])return;const card=document.querySelector('[data-gallery="'+id+'"]');if(!card)return;const img=card.querySelector('.gallery-main');img.src=pic(i,view);img.alt=i.title+' — '+VIEW_NAMES[view].toLowerCase()+', sample illustration';card.querySelectorAll('.gallery-thumb').forEach((button,n)=>button.setAttribute('aria-pressed',String(n===view)));}

let filters={q:'',cat:'All equipment',city:'All locations',kind:'All'};
function home(){const visible=S.items.filter(i=>i.status==='available'&&!allocation(i.id)&&!i.hold);return `<section class="photo-hero" aria-label="Neighbors helping neighbors"><img class="hero-background" src="assets/hero-bay-area.png" alt="An older wheelchair user and companion overlooking San Francisco Bay and the Golden Gate Bridge"><div class="hero-copy"><h1>Neighbors Helping Neighbors</h1><p>Find free medical equipment nearby, or give something you no longer need a new purpose.</p><div class="actions">${btn('Find free equipment →','browse','','primary')}${btn('Donate equipment','donate')}</div><p class="hero-footnote">For every age and income. No insurance paperwork.</p></div></section><section class="journey-strip" aria-label="How it works"><div class="journey-links"><a class="journey-link" href="#browse"><span class="journey-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/></svg></span><span><small>STEP 1</small><strong>Find Free Equipment <span aria-hidden="true">→</span></strong><span>Browse equipment categories.</span></span></a><a class="journey-link" href="#how/connect"><span class="journey-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M3 4h18v12H9l-6 4V4Z"/><path d="M7 8h10M7 12h6"/></svg></span><span><small>STEP 2</small><strong>Connect with Donor <span aria-hidden="true">→</span></strong><span>Request, receive an offer, and accept.</span></span></a><a class="journey-link" href="#how/handoff"><span class="journey-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/></svg></span><span><small>STEP 3</small><strong>Arrange a safe handoff <span aria-hidden="true">→</span></strong><span>Plan a public, daytime meeting.</span></span></a></div></section><div class="trust"><span>✓ Always free equipment</span><span>✓ Alameda & Contra Costa counties</span><span>✓ Caregivers welcome</span></div><section class="section"><div class="section-head"><div><p class="eyebrow">A new chapter starts nearby</p><h2>Equipment from your community</h2></div>${link('See all equipment →','browse')}</div><p class="muted">Illustrated sample listings for design review. Availability is fictional.</p><div class="grid">${visible.slice(0,3).map(card).join('')}</div></section>`;}
function browse(){const items=S.items.filter(i=>i.status==='available'&&!i.hold&&!allocation(i.id)&&(filters.cat==='All equipment'||i.cat===filters.cat)&&(filters.city==='All locations'||i.city===filters.city)&&(filters.kind==='All'||i.kind===filters.kind)&&(i.title+' '+i.cat).toLowerCase().includes(filters.q.toLowerCase()));return `<p class="eyebrow">Find a little support nearby</p><h1>Free equipment. Local connections.</h1><p class="muted">Browse freely. Sign in only when you’re ready to request an item.</p><div class="filters"><label>Search equipment<input id="search" value="${e(filters.q)}" placeholder="Try walker or shower chair"></label><label>Town<select id="city">${['All locations','Oakland','Berkeley','Walnut Creek','Richmond','Concord'].map(x=>`<option ${filters.city===x?'selected':''}>${x}</option>`).join('')}</select></label><label>Gift or loan<select id="kind">${[['All','Gifts & loans'],['gift','Free to keep'],['loan','Free loan']].map(x=>`<option value="${x[0]}" ${filters.kind===x[0]?'selected':''}>${x[1]}</option>`).join('')}</select></label></div><div class="category-row">${['All equipment',...CATS].map(x=>btn(e(x),'category',x,'chip '+(filters.cat===x?'active':''))).join('')}</div><p role="status"><b>${items.length} items</b></p>${items.length?`<div class="grid">${items.map(card).join('')}</div>`:`<div class="empty"><h2>No matching equipment yet</h2><p>Try another category or town. Availability is never guaranteed.</p>${btn('Reset filters','resetfilters')} ${link('Explore resources and help →','resources')}</div>`}`;}
function detailPhoto(view){const g=document.querySelector('.detail-gallery');if(!g)return;const i=item(g.dataset.item);const v=((Number(view)%VIEW_NAMES.length)+VIEW_NAMES.length)%VIEW_NAMES.length;g.dataset.view=v;const img=g.querySelector('.detail-image');img.src=pic(i,v);img.alt=i.title+' — '+VIEW_NAMES[v].toLowerCase()+', sample illustration';g.querySelector('.rotator-status').textContent=(v+1)+' / '+VIEW_NAMES.length+' · '+VIEW_NAMES[v];g.querySelectorAll('.gallery-thumb').forEach((b,n)=>b.setAttribute('aria-pressed',String(n===v)));}
function rotatePhoto(delta){const g=document.querySelector('.detail-gallery');if(g)detailPhoto(Number(g.dataset.view)+Number(delta));}
function donorRequestPanel(i){if(!S.signed||S.role!=='donor'||i.owner!==PEOPLE.donor.name)return '';const r=allocation(i.id);if(!r)return '';const blocked=i.hold||r.paused||(i.kind==='loan'&&(!r.consent||S.evidence!=='reviewed'));return `<section class="panel donor-request-panel" aria-label="Donor request review"><span class="badge">${r.state==='pending'?'Action needed: pending request':status(r.state)}</span><h2 style="font-size:25px;margin-top:16px">${r.state==='pending'?'Review Maya’s request':r.state==='offered'?'Waiting for recipient acceptance':'Your exchange'}</h2><p>${e(r.id)} · ${r.caregiver?'Maya is helping someone else.':'Requested by Maya.'}</p>${i.kind==='loan'?`<p>Requested loan: ${r.loanDays} days. ${r.consent?'Disclosure consent recorded.':'Disclosure consent missing or revoked.'}</p>`:''}${r.state==='pending'?`<p>Respond by ${date(r.created+48*3600000)}. Approval creates an offer; Maya then has 24 hours to accept and reserve the item.</p>`:''}${r.state==='offered'?`<p>Offer made. Maya must accept by ${date(r.offered+24*3600000)}. This item is not reserved yet.</p>`:''}${blocked?'<div class="note warn">Approval is blocked by a safety hold, messaging pause, or missing loan evidence/consent. Resolve the issue before progressing.</div>':''}<div class="actions">${r.state==='pending'?`<button class="primary" data-action="offer" data-id="${r.id}" ${blocked?'disabled':''}>Approve & make offer</button>${btn('Decline, keep available','decline',r.id)}${btn('Item unavailable','unavailable',r.id)}`:''}${r.state==='reserved'?btn('Confirm handoff','handoff',r.id,'primary'):''}${r.state==='loaned'?btn('Confirm returned','return',r.id,'primary'):''}${i.kind==='loan'?btn('Borrower disclosure','disclosure',r.id):''}${link('Back to My Activity','activity')}</div>${requesterEvidenceView(r)}${handoffSuggestionView(r,i)}</section>`;}
function detail(id){const i=item(id);if(!i)return '<h1>Item not found</h1>';if(!['available','reserved','loaned','donated'].includes(i.status)&&S.role!=='donor'&&S.role!=='moderator')return '<h1>This listing is not available</h1>'+link('Return to equipment','browse');const a=allocation(i.id);const available=i.status==='available'&&!i.hold&&!a;const donatedForOwner=S.signed&&S.role==='donor'&&i.status==='donated';const reserved=i.status==='reserved';const pendingForOwner=S.signed&&S.role==='donor'&&a?.state==='pending';const lastRequest=S.requests.filter(r=>r.item===i.id).at(-1);const pendingExpiredForOwner=S.signed&&S.role==='donor'&&i.status==='unavailable'&&!a&&lastRequest?.state==='expired'&&(lastRequest.expiredFrom==='pending'||(!lastRequest.expiredFrom&&!lastRequest.offered));return `${link('← Back to equipment','browse','back')}<div class="split"><div><section class="detail-gallery" data-item="${i.id}" data-view="0" aria-label="${e(i.title)} images" aria-roledescription="carousel"><div class="detail-art swipe-area" tabindex="0" aria-label="Equipment image. Swipe or use left and right arrow keys to change views."><img class="detail-image" src="${pic(i)}" alt="${e(i.title)} — full view, sample illustration" draggable="false"></div><div class="rotator-controls"><button data-action="rotate" data-id="-1" aria-label="Previous image">←</button><span class="rotator-status" role="status" aria-live="polite">1 / ${VIEW_NAMES.length} · Full view</span><button data-action="rotate" data-id="1" aria-label="Next image">→</button></div><div class="gallery-thumbs" role="group" aria-label="Choose equipment image">${VIEW_NAMES.map((name,v)=>`<button class="gallery-thumb" data-action="detailphoto" data-id="${v}" aria-label="Show ${name.toLowerCase()}" aria-pressed="${v===0}"><img src="${pic(i,v)}" alt=""><span>${name}</span></button>`).join('')}</div><p class="swipe-hint">Swipe images, use arrow keys, or select a thumbnail.</p></section><small>Illustration only · No actual equipment is being offered.</small>${guidance}</div><div>${badge(i)}<h1 style="font-size:42px;margin-top:20px">${e(i.title)}</h1>${donatedForOwner?'<div class="note" role="status"><strong>DONATED</strong>. New requests are closed.</div>':reserved?'<div class="note" role="status"><strong>RESERVED</strong> New requests are closed</div>':pendingForOwner?'<div class="note warn" role="status">This item is held for one requester. New requests are closed.</div>':pendingExpiredForOwner?`<section class="note warn" aria-label="Expired pending request"><strong>Pending Request Expired</strong><p>The recipient’s request expired after 48 hours without a donor response. Confirm that you still have the item and it is available before reopening it.</p>${btn('Confirm availability & make available again','reopen',i.id,'primary')}${i.hold?'<p>A safety hold must be resolved before this item can reopen.</p>':''}</section>`:''}${donorRequestPanel(i)}<p class="muted">⌖ ${e(i.city)}</p><p>${e(i.desc)}</p><div class="data"><div><small>Condition</small>${e(i.condition)} <small>Self-attested, not inspected</small></div><div><small>Offered by</small>${e(i.owner)}</div><div><small>Manufacturer / model</small>${e(i.model)}</div><div><small>Collection</small>Weekday daylight hours</div><div><small>Cleaning</small>${e(i.clean)}</div></div><div class="note"><b>Donor disclosures</b><br>${e(i.defects)}<br>Capacity is not provided in this sample. Ask a qualified professional about fit and follow manufacturer instructions.</div>${i.kind==='loan'?'<p class="muted">Loan preview uses fictional evidence only. Loan launch and privacy rules remain subject to DEC01/DEC03.</p>':''}${donatedForOwner||reserved||pendingForOwner||pendingExpiredForOwner?'':available?'<div class="actions">'+btn(i.kind==='loan'?'Request this loan':'Request this item','request',i.id,'primary')+btn('Ask A Question','ask-question',i.id)+'</div>':`<div class="note warn">${i.hold?'Safety review in progress':a?'This item is held for one requester.':status(i.status)}. New requests are closed.</div>`}<div class="actions">${btn('Report a concern','report',i.id)}${btn('Copy public listing link','share',i.id)}</div><small>Verified phone access does not establish identity or equipment safety.</small></div></div>`;}
function progress(r){const index=['pending','offered','reserved','loaned','completed'].indexOf(r.state);return `<div class="progress">${['Request','Donor offer','Reservation','Handoff'].map((x,k)=>`<span class="${k<=index?'done':''}">${x}</span>`).join('')}</div>`;}
function recipientPickupContact(r,i){if(!S.signed||S.role!=='recipient'||r.state!=='reserved'||r.paused||i.hold)return '';return `<section class="note pickup-contact" aria-label="Contact donor for pickup"><h3>Arrange pickup with your donor</h3><p><strong>Donor:</strong> ${e(i.owner)}</p><p>Confirm the item and any access or transport arrangements before you travel.</p><p>Choose a public, nonresidential place and meet in daylight while the venue is open. You and the donor arrange pickup; FreeDME does not arrange transport.</p><p>FreeDME is not responsible for any travel related issues, incidents, no-shows or unsuccessful transfer of equipment for any other reasons.</p></section>`;}
function expiredRecipientRequest(id){if(!S.signed||S.role!=='recipient')throw Error('Recipient access required.');const r=request(id);if(!r||r.state!=='expired')throw Error('Only expired requests can use this action.');return r;}
function retryItem(id){expire();const r=expiredRecipientRequest(id);const i=item(r.item);if(!i||i.status!=='available'||i.hold||allocation(i.id))throw Error('This item is not available for a new request yet. The donor must confirm possession and availability before reopening it. Check Find Equipment for other available items.');return i.id;}
function removeExpiredRequest(id){const r=expiredRecipientRequest(id);r.hiddenForRecipient=true;save();}
function restoreExpiredRequests(){if(!S.signed||S.role!=='recipient')throw Error('Recipient access required.');S.requests.forEach(r=>{if(r.state==='expired'&&!r.replacedBy)delete r.hiddenForRecipient;});save();}
function questionDialog(id){const i=item(id);if(!i||i.status!=='available'||i.hold||allocation(i.id))throw Error('This item is not accepting questions.');modal(`<h2>Ask A Question</h2><p>About ${e(i.title)}</p><form id="item-question" data-item="${i.id}"><label>Your question<textarea name="question" required maxlength="500" rows="5" placeholder="Ask about dimensions, condition or features. Use fictional details only."></textarea></label><p class="muted">Do not include phone numbers, addresses or medical details. A simulated SMS will notify the donor; no real text is sent.</p><button class="primary">Submit question</button></form>`);}
function addQuestion(id,text){const i=item(id);text=String(text||'').trim();if(!i||i.status!=='available'||i.hold||allocation(i.id))throw Error('This item is not accepting questions.');if(!text||text.length>500)throw Error('Enter a question of 1–500 characters.');if(/@|https?:|\b\d{3}[- .]?\d{3}[- .]?\d{4}\b/i.test(text))throw Error('Remove private contact details from your question.');S.questions=S.questions||[];const q={id:'Q'+(S.questions.length+1),item:i.id,text,sender:S.role==='recipient'?(S.registrationProfile?.displayName||'Maya'):'Interested recipient',created:S.time,state:'pending',notification:S.sms?'Simulated SMS notification — not sent':'SMS suppressed: routine texts off',sms:'An interested recipient has a question about your equipment. Open My Activity on FreeDME to review it.'};S.questions.push(q);event('Question '+q.id+' saved; '+q.notification);save();return q;}
function answerQuestion(id,text){if(!S.signed||S.role!=='donor')throw Error('Donor sign-in required.');const q=(S.questions||[]).find(q=>q.id===id);if(!q||q.state==='answered')throw Error('This question is missing or already answered.');if(item(q.item)?.hold)throw Error('Resolve the equipment safety hold before answering.');text=String(text||'').trim();if(!text||text.length>1000)throw Error('Enter an answer of 1–1000 characters.');if(/@|https?:|\b\d{3}[- .]?\d{3}[- .]?\d{4}\b/i.test(text))throw Error('Remove private contact details from your answer.');q.answer=text;q.answered=S.time;q.state='answered';q.answerNotification=S.sms?'Simulated SMS notification — not sent':'SMS suppressed: routine texts off';q.answerSms='The donor has answered your equipment question. Open My Activity on FreeDME to read the answer.';event('Answer saved for '+q.id+'; '+q.answerNotification);save();return q;}
function answerDialog(id){if(!S.signed||S.role!=='donor')throw Error('Donor sign-in required.');const q=(S.questions||[]).find(q=>q.id===id);if(!q||q.state==='answered')throw Error('This question is missing or already answered.');modal(`<h2>Answer question</h2><h3>${e(item(q.item)?.title||'Equipment')}</h3><p style="white-space:pre-wrap"><strong>Question:</strong> ${e(q.text)}</p><form id="question-answer" data-question="${e(q.id)}"><label>Your answer<textarea name="answer" required maxlength="1000" rows="5"></textarea></label><p>Use fictional details only. Do not include private contact, address or medical details. The recipient receives a simulated SMS notification; no real text is sent.</p><button class="primary">Submit answer</button></form>`);}
function recipientQuestions(){const qs=S.questions||[];const groups=[...new Set(qs.slice().reverse().map(q=>q.item))];return `<section class="panel"><h2>Questions &amp; Answers</h2>${qs.length?groups.map(id=>`<article class="panel"><h3>${link(e(item(id)?.title||'Equipment'),'item/'+id)}</h3>${qs.filter(q=>q.item===id).slice().reverse().map(q=>`<div class="panel"><small>Question ${e(q.id)}</small> <span class="badge">${q.state==='answered'?'Answered':'Awaiting answer'}</span><p style="white-space:pre-wrap"><strong>Your question:</strong> ${e(q.text)}</p><small>Asked ${date(q.created)}</small>${q.state==='answered'?`<p style="white-space:pre-wrap"><strong>Donor’s answer:</strong> ${e(q.answer)}</p><small>Answered ${date(q.answered)} · ${e(q.answerNotification)}</small><details><summary>SMS notification preview</summary><p>${e(q.answerSms)}</p><p>No real SMS was sent.</p></details>`:'<p>The donor has not answered yet.</p>'}</div>`).join('')}<div class="actions">${btn('Ask Another Question','ask-question',id)}</div></article>`).join(''):'<p>No questions yet. Use Ask A Question on an available item.</p>'}</section>`;}
function donorQuestions(){const qs=(S.questions||[]).filter(q=>q.state!=='answered');return `<section class="panel"><h2>Pending questions (${qs.length})</h2>${qs.length?qs.map(q=>`<article class="list-row"><div><h3>${link(e(item(q.item)?.title||'Equipment'),'item/'+q.item)}</h3><p>From ${e(q.sender)} · ${date(q.created)}</p><p style="white-space:pre-wrap">${e(q.text)}</p><small>${e(q.notification)}</small><details><summary>SMS notification preview</summary><p>${e(q.sms)}</p><p>No real SMS was sent.</p></details></div>${btn('Answer','answer-question',q.id)}</article>`).join(''):'<p>No pending questions.</p>'}</section>`;}
let donorTab='questions';
const donorTabLabels={questions:'Pending Questions',equipment:'Your Equipment',handoffs:'Requests & Handoffs'};
function donorTabs(){return `<style>.donor-tabs{display:flex;overflow-x:auto;border-bottom:1px solid #bacbc8;margin:24px 0;background:#f4faf8}.donor-tabs [role=tab]{position:relative;flex:1;min-width:145px;min-height:56px;border:0;border-radius:0;background:transparent;color:#465956;font-family:inherit;font-weight:600;font-size:14px;line-height:1.4;padding:16px 20px;white-space:nowrap}.donor-tabs [role=tab]:hover{background:#e3efec}.donor-tabs [aria-selected=true]{color:#006b60}.donor-tabs [aria-selected=true]::after{content:'';position:absolute;bottom:0;height:3px;border-radius:3px 3px 0 0;background:#006b60;left:20%;right:20%}.donor-tabs [role=tab]:focus-visible{outline:3px solid #006b60;outline-offset:-4px}.donor-tab-panel[hidden]{display:none}</style><div class="donor-tabs" role="tablist" aria-label="Donor activity">${Object.entries(donorTabLabels).map(([id,label])=>`<button type="button" role="tab" id="donor-tab-${id}" aria-controls="donor-panel-${id}" aria-selected="${donorTab===id}" tabindex="${donorTab===id?0:-1}" data-action="donor-tab" data-id="${id}">${label}</button>`).join('')}</div>`;}
function donorPanel(id){return `<section class="donor-tab-panel" role="tabpanel" tabindex="0" id="donor-panel-${id}" aria-labelledby="donor-tab-${id}" ${donorTab===id?'':'hidden'}>`;}
function selectDonorTab(id){if(!donorTabLabels[id])return;donorTab=id;for(const key of Object.keys(donorTabLabels)){const tab=document.getElementById('donor-tab-'+key),panel=document.getElementById('donor-panel-'+key);if(tab){tab.setAttribute('aria-selected',String(key===id));tab.tabIndex=key===id?0:-1;}if(panel)panel.hidden=key!==id;}document.getElementById('donor-tab-'+id)?.focus();}
let recipientTab='questions';
const recipientTabLabels={questions:'Questions & Answers',requests:'Requests & Offers'};
function recipientTabs(){return `<style>.recipient-tabs{display:flex;overflow-x:auto;border-bottom:1px solid #bacbc8;margin:24px 0;background:#f4faf8}.recipient-tabs [role=tab]{position:relative;flex:1;min-width:145px;min-height:56px;border:0;border-radius:0;background:transparent;color:#465956;font-family:inherit;font-weight:600;font-size:14px;line-height:1.4;padding:16px 20px;white-space:nowrap}.recipient-tabs [role=tab]:hover{background:#e3efec}.recipient-tabs [aria-selected=true]{color:#006b60}.recipient-tabs [aria-selected=true]::after{content:'';position:absolute;bottom:0;height:3px;border-radius:3px 3px 0 0;background:#006b60;left:20%;right:20%}.recipient-tabs [role=tab]:focus-visible{outline:3px solid #006b60;outline-offset:-4px}.recipient-tab-panel[hidden]{display:none}</style><div class="recipient-tabs" role="tablist" aria-label="Recipient activity">${Object.entries(recipientTabLabels).map(([id,label])=>`<button type="button" role="tab" id="recipient-tab-${id}" aria-controls="recipient-panel-${id}" aria-selected="${recipientTab===id}" tabindex="${recipientTab===id?0:-1}" data-action="recipient-tab" data-id="${id}">${label}</button>`).join('')}</div>`;}
function recipientPanel(id){return `<section class="recipient-tab-panel" role="tabpanel" tabindex="0" id="recipient-panel-${id}" aria-labelledby="recipient-tab-${id}" ${recipientTab===id?'':'hidden'}>`;}
function selectRecipientTab(id){if(!recipientTabLabels[id])return;recipientTab=id;for(const key of Object.keys(recipientTabLabels)){const tab=document.getElementById('recipient-tab-'+key),panel=document.getElementById('recipient-panel-'+key);if(tab){tab.setAttribute('aria-selected',String(key===id));tab.tabIndex=key===id?0:-1;}if(panel)panel.hidden=key!==id;}document.getElementById('recipient-tab-'+id)?.focus();}
function activity(){if(!S.signed)return `<div class="empty"><h1>Your activity, all in one place.</h1><p>Use a fictional account to explore requests, offers and listings.</p>${btn('Try recipient sign-in','signin','recipient','primary')} ${btn('Try donor sign-in','signin','donor')}</div>`;if(S.role==='moderator')return moderator();const donor=S.role==='donor';const visibleRequests=S.requests.filter(r=>donor||!r.hiddenForRecipient);return `<p class="eyebrow">${donor?'Your donations':'Your requests'}</p><h1>Hello, ${e(S.registrationProfile?.displayName||PEOPLE[S.role].name)}.</h1><p class="muted">${donor?'A small act can make a meaningful difference.':'Your next step toward the equipment you need.'}</p><div class="note">Routine SMS is <b>${S.sms?'on':'off'}</b> in this simulation. Tasks stay here either way. ${btn(S.sms?'Turn routine SMS off':'Review SMS consent','sms')}</div>${donor?donorTabs()+donorPanel('questions')+donorQuestions()+'</section>'+donorPanel('equipment'):recipientTabs()+recipientPanel('questions')+recipientQuestions()+'</section>'}${donor?`<div class="section-head"><h2>Your equipment</h2>${btn('Add equipment','donate','','primary')}</div><div class="panel">${S.items.map(i=>`<div class="list-row"><div><span class="badge ${i.hold?'hold':''}">${i.hold?'Safety hold':allocation(i.id)?.state==='pending'?'Pending request':allocation(i.id)?.state==='offered'?'Offer awaiting acceptance':status(i.status)}</span><h3>${link(e(i.title),'item/'+i.id)}</h3><p>${e(i.city)} · ${i.kind==='gift'?'Free to keep':'Free loan'}</p></div><div class="actions">${btn(allocation(i.id)?.state==='pending'?'Review request':'View','detail',i.id,allocation(i.id)?.state==='pending'?'primary':'')}${['unavailable','withdrawn','donated'].includes(i.status)?btn('Confirm & reopen','reopen',i.id):''}${['available','pending_review','rejected'].includes(i.status)?btn('Edit listing','edit',i.id):''}${!['withdrawn','donated'].includes(i.status)?btn('Withdraw','withdraw',i.id):''}</div></div>`).join('')}</div>`:''}${donor?'</section>'+donorPanel('handoffs'):recipientPanel('requests')}<h2>${donor?'Requests & handoffs':'Requests & offers'}</h2>${!donor&&S.requests.some(r=>r.hiddenForRecipient&&!r.replacedBy)?`<p>${btn('Restore removed requests','restorerequests')}</p>`:''}${visibleRequests.length?visibleRequests.slice().reverse().map(r=>{const i=item(r.item);return `<article class="panel"><div class="section-head"><div><span class="badge ${r.paused?'warn':''}">${r.paused?'Paused: '+e(r.paused):status(r.state)}</span><h3 style="margin-top:10px">${link(e(i.title),'item/'+i.id)}</h3>${!donor&&r.state==='expired'?`<div class="actions">${btn('Request Again','retryrequest',r.id,'primary')}${btn('Remove Request','removerequest',r.id)}</div>`:''}</div><small>${r.id}</small></div>${progress(r)}<p>${r.state==='completed'||(!donor&&i.kind==='loan'&&r.state==='loaned')?'':r.caregiver?'Maya is helping someone else.':'Requested by Maya.'} ${r.state==='pending'?'Donor response closes at '+date(r.created+48*3600000):r.state==='offered'?'Accept before '+date(r.offered+24*3600000):r.state==='reserved'?'Reserved. Arrange a public daytime handoff directly.':''}</p>${requesterEvidenceView(r)}${handoffSuggestionView(r,i)}${recipientPickupContact(r,i)}${r.paused?'<div class="note warn">This exchange is paused. Your request is saved. Use the support route; do not start an in-account conversation.</div>':''}${i.kind==='loan'?`<p>${!donor&&r.state==='loaned'?'Remaining loan period':'Requested period'}: ${r.loanDays} days. ${r.consent?'Request-specific disclosure consent recorded.':'Consent revoked; loan progression blocked.'}</p>`:''}<div class="actions">${donor&&r.state==='pending'?btn('Approve','offer',r.id,'primary')+btn('Decline','decline',r.id)+btn('Unavailable','unavailable',r.id):''}${!donor&&r.state==='offered'?btn('Accept & reserve','accept',r.id,'primary'):''}${!donor&&['pending','offered','reserved'].includes(r.state)?btn('Cancel request','cancel',r.id):''}${r.state==='reserved'?btn('Confirm handoff','handoff',r.id,'primary'):''}${donor&&r.state==='loaned'?btn('Confirm returned','return',r.id,'primary')+btn('Report non-return','report',i.id):''}${donor&&i.kind==='loan'?btn('Borrower disclosure','disclosure',r.id):''}${!donor&&i.kind==='loan'&&r.consent&&!r.handoff&&['pending','offered','reserved'].includes(r.state)?btn('Revoke disclosure consent','revoke',r.id):''}${['reserved','loaned'].includes(r.state)?btn('Pickup & return guidance','guidance'):''}${donor&&r.state==='pending'?'':btn('Report an issue','report',i.id)}</div><details style="margin-top:18px"><summary>Activity history</summary><ul class="timeline">${r.history.map(x=>`<li>${e(x)}</li>`).join('')}</ul></details><small>${r.handoff?'Handoff confirmed by '+(r.handoffBy==='recipient'?'recipient':'donor')+': '+date(r.handoff):'Physical handoff not confirmed.'} ${r.returned?'Return confirmed: '+date(r.returned):''}</small></article>`;}).join(''):'<div class="empty"><h3>No requests yet</h3><p>Browse equipment to try the request → offer → reservation journey.</p>'+link('Find equipment →','browse')+'</div>'}</section>`;}
function moderator(){const pending=S.items.filter(i=>['pending_review','rejected'].includes(i.status));return `<p class="eyebrow">Restricted staff area · simulated access</p><h1>Community care, behind the scenes.</h1><p class="muted">Screen listings, respond to concerns and keep participants informed. Review is not a physical inspection.</p><div class="grid"><div class="stat"><strong>${pending.length}</strong>Listings needing attention</div><div class="stat"><strong>${S.cases.filter(c=>c.state!=='closed').length}</strong>Open cases</div><div class="stat"><strong>${S.requests.filter(r=>r.reserved&&!['cancelled','closed_unavailable'].includes(r.state)).length}</strong>Successful reservations <small>· Not confirmed transfers</small></div></div><div class="section"><h2>Listing review queue</h2><div class="panel">${pending.length?pending.map(i=>`<div class="list-row"><div><h3>${e(i.title)}</h3><p>${e(i.city)} · ${e(i.model)}</p><small>${i.hold?'Unresolved safety / identification hold':'Screening required before publication'}</small></div>${btn('Review listing','review',i.id,'primary')}</div>`).join(''):'<p>No listings awaiting review.</p>'}</div><h2>Restricted tasks, incidents & support queue</h2><div class="panel">${S.cases.map(c=>`<div class="list-row"><div><span class="badge ${c.severity==='urgent'?'hold':''}">${e(c.severity)} · ${e(c.state)}</span><h3 style="margin-top:12px">${e(c.reason)}</h3><p>${c.id} · Owner: ${e(c.owner)} · ${item(c.item)?e(item(c.item).title):'General help'}</p><small>${c.kind==='handoff_followup'?'Automatic follow-up · '+e(c.requestId)+' · Contact donor and recipient':'Reporter: Maya (fictional). Staff-only case detail.'}</small></div>${btn('Open case','case',c.id)}</div>`).join('')}</div><h2>Separate outcomes</h2><div class="grid"><div class="stat"><strong>${S.requests.filter(r=>r.handoff).length}</strong>Participant-confirmed handoffs</div><div class="stat"><strong>${S.requests.filter(r=>r.returned).length}</strong>Confirmed loan returns</div><div class="stat"><strong>${S.cases.filter(c=>c.reason==='Transport barrier').length}</strong>Transport barriers</div></div><div class="note warn">Support hours and response targets are not approved (DEC04). No real emergency or support service is operating in this prototype.</div><details><summary>Simulation audit trail</summary><div class="log">${S.events.map(v=>`<p>${date(v.at)} · ${e(v.text)}</p>`).join('')||'No events yet.'}</div></details></div>`;}
function loanToday(){return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Los_Angeles',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date(S.time));}
function loanDaysUntil(value){if(!/^\d{4}-\d{2}-\d{2}$/.test(value||''))throw Error('Select a Loan Until date.');const end=Date.parse(value+'T00:00:00Z');if(!Number.isFinite(end)||new Date(end).toISOString().slice(0,10)!==value)throw Error('Select a valid Loan Until date.');const days=(end-Date.parse(loanToday()+'T00:00:00Z'))/86400000;if(days<1)throw Error('Loan Until must be after the current sample date.');return days;}
function donate(editId){if(S.role!=='donor'||!S.signed)return accessForm('donor');const i=item(editId);return `<p class="eyebrow">${i?'Update your listing':'Make room for a little kindness'}</p><h1>${i?'Edit equipment':'Offer equipment to a neighbor.'}</h1><p class="muted">Use sample content only. Submitted listings stay private until a moderator screens them.</p><div class="steps"><span class="active">1 · Describe</span><span>2 · Submit for review</span><span>3 · Connect</span></div><form id="donate-form" data-edit="${i?.id||''}" class="panel reading"><div class="form-grid"><div class="wide"><label>Listing title<input name="title" maxlength="90" required value="${e(i?.title||'')}" placeholder="Example: Folding walker"></label></div><div><label>Category<select name="cat">${CATS.map(x=>`<option ${i?.cat===x?'selected':''}>${x}</option>`).join('')}</select></label></div><div><label>Location<input name="city" required maxlength="100" value="${e(i?.city||S.registrationProfile?.location||'')}" placeholder="ZIP code or town name" aria-describedby="location-help"></label><small id="location-help">Enter a ZIP code (for example, 94612) or town name (for example, Oakland). Do not enter a street address.</small></div><div><label>Gift or loan<select name="kind"><option value="gift">Free gift to keep</option><option value="loan" ${i?.kind==='loan'?'selected':''}>Free loan (design simulation)</option></select></label></div><div><label>Loan Until<input type="date" name="loanUntil" min="${loanToday()}" value="${e(i?.loanUntil||'')}" ${i?.kind==='loan'?'required':'disabled'} aria-describedby="loan-until-help"></label><small id="loan-until-help">Choose the day, month and year the loan must end. Required for loans only. Current sample date: ${loanToday()}.</small></div><div><label>Condition<select name="condition">${['New','Gently used','Good','Requires Repairs'].map(c=>`<option ${c===(i?.condition||'Gently used')?'selected':''}>${c}</option>`).join('')}</select></label></div><div><label>Manufacturer / model<input name="model" required value="${e(i?.model||'Unknown')}" maxlength="80"></label></div><div class="wide"><label>Description<textarea name="desc" required maxlength="500">${e(i?.desc||'')}</textarea></label></div>${i?`<div><label>Missing parts / known defects<textarea name="defects" required>${e(i.defects)}</textarea></label></div>`:`<div class="wide"><label><input type="checkbox" name="noDefects" required> No known missing parts</label></div>`}<div><label>Modifications<textarea name="mods" required>None known</textarea></label></div><div><label>Cleaning status<select name="clean"><option>Cleaned by donor</option><option>Not cleaned</option><option>Unknown</option></select></label></div><div><label>Pickup availability<input name="pickup" required value="Weekday daylight hours"></label></div></div><label>Sample photos — select 1 to 5</label><p><small>These stand in for photos. Real uploads and metadata processing are not enabled.</small></p><div class="photo-choices">${[0,1,2].map((x)=>`<label><input type="checkbox" name="photos" value="${x}" ${x===0?'checked':''}><img src="assets/0.svg" alt="Sample equipment view ${x+1}">View ${x+1}</label>`).join('')}</div>${check('free','I am authorized to offer this item, and it is completely free.')}${check('truth','My sample disclosures are truthful to the best of my knowledge.')}${check('terms','I acknowledge the donor agreement and public daytime handoff guidance (preview policy v0.9).')}<p class="error-text" id="form-error" role="alert"></p><div class="actions"><button class="primary" type="submit">${i?'Submit changes for re-review':'Submit for review'}</button>${btn('Fill sample details','filldonor')}</div><small>Public fields cannot include private contact or address details. Private donor contact would come from the verified account. Category configuration and territory enforcement await approved policies.</small></form>`;}
function how(){return `<div class="reading"><p class="eyebrow">A clear path, a thoughtful handoff</p><h1>Neighbors helping neighbors.</h1><h2 id="connect" tabindex="-1">For people giving</h2><p>Describe one item and provide 1–5 photographs. A moderator reviews the listing and recall information before publication. Respond to one requester at a time. Making an offer is not a reservation: the recipient must accept.</p><h2>For people receiving</h2><p>Browse without an account. Sign in by phone code when requesting. Gifts have no identity-document or address-validation requirement. Loans have a separate evidence and request-specific consent step, subject to approved privacy controls.</p><p>A caregiver or community helper can use their own account to assist someone else.</p><div id="handoff" tabindex="-1">${guidance}</div><h2>Know what the service can and cannot do</h2><p>Equipment is free. FreeDME does not inspect, certify, fit, repair, assemble, deliver or guarantee return of equipment. Condition and capacity are donor-reported. Seek qualified advice for fit and use; do not test uncertain equipment by putting yourself at risk.</p><h2>When plans change</h2><p>Cancel or report a concern in My activity. A cancellation, due date or silence never automatically makes a reserved item available. The donor must confirm possession and availability, and safety holds must be resolved.</p><h2>Time to respond</h2><p>Pending requests receive a reminder at 24 hours and close at 48 hours. Offers last 24 hours. Details of other reminders, listing freshness and loan timing remain open for approval.</p><div class="actions">${btn('Find equipment','browse','','primary')}${btn('Donate equipment','donate')}</div></div>`;}
function resources(){return `<div class="reading"><p class="eyebrow">You don’t have to figure it out alone</p><h1>A little help with the next step.</h1><p>If there’s no suitable item, try another category or a broader area. Equipment availability and transportation are never guaranteed.</p><div class="grid two"><article class="panel"><h3>Help using FreeDME</h3><p>Account access, caregiver help, or trouble with a request.</p>${btn('Try a sample help request','help','','primary')}</article><article class="panel"><h3>Pickup is a barrier?</h3><p>Record the barrier on your request. FreeDME does not arrange transport.</p>${link('Go to My activity →','activity')}</article></div><h2>Community resource directory preview</h2><p>The PRS names candidate organizations, including ReCARES and Ability Tools. These have not been verified here. This prototype does not claim partnerships, current eligibility, stock, hours or transport service.</p><div class="panel"><span class="badge warn">Publication pending review</span><h3 style="margin-top:20px">Resource records will distinguish</h3><ul><li>Free equipment donations</li><li>Temporary equipment loans</li><li>Mixed-cost exchanges</li><li>Referral-only organizations</li></ul><p>Each published record needs verified official contact details, service area, cost model, restrictions, review date and reviewer.</p></div><div class="note warn">The support telephone number, staffed hours and response targets are not yet approved. No real support is available here. This is not an emergency service.</div></div>`;}
const DEC=[['DEC01','Loan launch','Gifts and loans remain in scope. Loans need privacy, evidence and dispute readiness before launch.'],['DEC02','Equipment configurations','Rollator classification and approved wheelchair configurations need a decision.'],['DEC03','Privacy and recovery','Evidence retention, consent duration, caregiver authority, deletion and recovery proof remain open.'],['DEC04','Support capacity','Named coverage, actual support hours and feasible response targets need approval.'],['DEC05','Messaging exceptions','Conversational SMS treatment, other nonresponse timers and opt-out recovery need approval.'],['DEC06','Freshness and loan timing','Renewal interval, month-to-day conversion, loan start and extension reminders remain open.']];
function decisions(){return `<div class="reading"><p class="eyebrow">Design review notes</p><h1>A prototype, not a launch decision.</h1><p>This design follows PRS v0.9. Role switching, sample OTP, fictional evidence and time controls exist only to help reviewers explore the experience. They must never appear in a production build (FR036).</p>${DEC.map(d=>`<div class="panel"><span class="badge warn">${d[0]} · Open</span><h3 style="margin-top:15px">${d[1]}</h3><p>${d[2]}</p></div>`).join('')}<h2>Scope of this prototype</h2><p>Interactive: browsing, combined filters, gift/loan requests, donor offers, reservations, cancellation, owner reopening, listing review, recall holds, cases, sample evidence revocation and routine SMS preference.</p><p>Simulated, not implemented: secure authorization, real OTP, SMS delivery, uploads, document extraction, live recall screening, location services, production storage, retention/deletion, rate limits, accessible recovery and staff operations. No real personal data should be entered.</p></div>`;}
function date(n){return new Date(n).toLocaleString('en-US',{month:'short',day:'numeric',hour:'numeric',minute:'2-digit',timeZone:'America/Los_Angeles'})+' PT';}
function render(focus=true){expire();const parts=(location.hash||'#home').slice(1).split('/');const route=parts[0];document.getElementById('main').innerHTML=route==='register'?registrationPage():route==='browse'?browse():route==='item'?detail(parts[1]):route==='activity'?activity():route==='donate'?donate(parts[1]):route==='how'?how():route==='resources'?resources():route==='decisions'?decisions():home();document.getElementById('identity').innerHTML=`<span>${S.signed?`${PEOPLE[S.role].role} preview · <b>${e(S.registrationProfile?.displayName||PEOPLE[S.role].name)}</b>`:'Browsing as a visitor'} · Sample time: ${date(S.time)}</span>${btn(S.signed?'Switch sample role':'Try a sample account','lab')}`;document.querySelectorAll('nav a').forEach(a=>a.setAttribute('aria-current',a.hash==='#'+route?'page':'false'));if(focus)document.getElementById('main').focus({preventScroll:true});if(route==='how'&&['connect','handoff'].includes(parts[1])){const target=document.getElementById(parts[1]);target.scrollIntoView({block:'start'});target.focus({preventScroll:true});}}
function toast(t){const el=document.getElementById('toast');el.textContent=t;el.style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.style.display='none',5000);}
function modal(html){document.getElementById('modal').innerHTML=html;const d=document.getElementById('dialog');if(!d.open)d.showModal();}
function close(){document.getElementById('dialog').close();}
function go(path){close();if(location.hash==='#'+path)render();else location.hash=path;window.scrollTo(0,0);}
function lab(){modal(`<h2 class="modal-title">Explore the design</h2><p>All accounts and data are fictional. Nothing is sent to a real person.</p><div class="actions">${Object.entries(PEOPLE).map(([k,v])=>btn(v.role,'signin',k)).join('')}</div><div class="divider"></div><h3>Walk through a gift</h3><ol><li>Recipient: request a walker.</li><li>Donor: make an offer in My activity.</li><li>Recipient: accept and reserve.</li><li>Donor or recipient: confirm handoff after the equipment is exchanged.</li></ol><p>Try a loan with sample evidence, or submit equipment then screen it as a moderator.</p><h3>Registration preview</h3><div class="actions">${btn('Sign out to try registration','registration-signout')}${btn('View welcome message preview','welcome-preview')}</div><h3>Review scenarios</h3><div class="actions">${btn('Advance 24 hours','advance','24')}${btn('Advance 48 hours','advance','48')}${btn('Advance 7 days','advance','168')}${btn('Simulate SMS failure','fail')}${btn('Revoke sample evidence','badevidence')}</div><div class="note">Simulation time: ${date(S.time)}. Pending/offer expiry and seven-day unconfirmed-handoff follow-ups use this sample clock.</div>${btn('Reset all sample data','reset','','danger')} ${link('See open decisions','decisions')}`);}
// Registration preview: fictional phone numbers and browser-local records only.
function registrationUsers(){return S.registrationUsers||(S.registrationUsers=[{mobile:'5105550100',displayName:'Jordan',location:'Oakland'},{mobile:'5105550101',displayName:'Maya',location:'Berkeley'}]);}
function normalizeMobile(value){let n=String(value||'').replace(/\D/g,'');if(n.length===11&&n[0]==='1')n=n.slice(1);if(!/^\d{10}$/.test(n))throw Error('Enter a ten-digit sample mobile number.');if(!/^(20255501\d\d|510555010[01])$/.test(n))throw Error('Use a fictional number from 202-555-0100 to 202-555-0199 in this preview.');return n;}
function accessForm(role,id=''){return `<div class="reading"><h1>Continue with your mobile</h1><p>Sign in or register to ${role==='donor'?'donate equipment':'request this item'}. After verification, return to where you left off.</p><div class="note">Design preview only. No real accounts or texts. New user: use 202-555-0100 through 202-555-0199. Existing sample user: 510-555-0100 or 510-555-0101.</div><form id="access-mobile" data-role="${e(role)}" data-item="${e(id)}"><label>Mobile phone number<input type="tel" name="mobile" autocomplete="off" required maxlength="25" placeholder="202-555-0100"></label><p role="alert" class="error-text"></p><button class="primary">Continue</button></form></div>`;}
function beginAccess(role,id,mobile){const phone=normalizeMobile(mobile);S.access={role,item:id?+id:null,mobile:phone};save();return registrationUsers().find(u=>u.mobile===phone);}
function registrationPage(){if(!S.access)return '<h1>Start with an equipment action</h1>'+link('Find equipment','browse')+' '+link('Donate equipment','donate');const a=S.access;return `<div class="reading"><h1>Create your account</h1><p>This sample mobile is not registered. Enter just these three details, then verify your mobile.</p><div class="note">Use fictional details only. This preview stores accounts in this browser; no backend account or SMS is created.</div><form id="registration-form"><label>Display name<input name="displayName" required maxlength="50" value="${e(a.displayName||'')}" autocomplete="off"></label><label>Approximate location<input name="location" required maxlength="100" placeholder="ZIP code or town name" value="${e(a.location||'')}" autocomplete="off"></label><small>Use a ZIP code or town name, not a street address.</small><label>Mobile phone number<input name="mobile" type="tel" required maxlength="25" value="${e(a.mobile)}" autocomplete="off"></label><p role="alert" class="error-text"></p><button class="primary">Verify mobile with sample OTP</button></form></div>`;}
function prepareRegistration(data){if(!S.access)throw Error('Start again from Donate or Request.');const displayName=String(data.displayName||'').trim(),location=String(data.location||'').trim(),mobile=normalizeMobile(data.mobile);if(!displayName||displayName.length>50)throw Error('Enter a display name of 1–50 characters.');if(!location||location.length>100)throw Error('Enter a ZIP code or town name.');if(/@|https?:|\b\d+\s+\w+\s+(street|lane|road|avenue|drive)\b/i.test(location))throw Error('Enter only a ZIP code or town name, not contact details or a street address.');S.access={...S.access,mobile,displayName,location};save();}
function startRegistrationCode(){if(!S.access)throw Error('Start again from Donate or Request.');S.access.challenge={attempts:0,expires:Date.now()+10*60000,used:false};save();modal(`<h2>Verify your mobile</h2><p>Sample mobile: ${e(S.access.mobile)}. Use <strong>123456</strong>. No SMS was sent.</p><form id="registration-otp"><label>Six-digit OTP<input name="code" required inputmode="numeric" pattern="[0-9]{6}" maxlength="6" autocomplete="off"></label><p role="alert" class="error-text"></p><button class="primary">Verify and continue</button></form><p>Preview code expires in 10 minutes and allows three attempts. These are demonstration settings, not approved production limits.</p>${btn('Send a new sample code','registration-resend')}`);}
function verifyRegistration(code,now=Date.now()){const a=S.access,c=a?.challenge;if(!c||c.used||c.attempts>=3||now>=c.expires)throw Error('This sample code is expired or invalidated. Request a new code.');if(code!=='123456'){c.attempts++;save();throw Error(c.attempts>=3?'Three incorrect codes. Request a new sample code.':'Incorrect sample code. Try again.');}let user=registrationUsers().find(u=>u.mobile===a.mobile);const created=!user;if(created){if(!a.displayName||!a.location)throw Error('Complete registration before verifying.');user={mobile:a.mobile,displayName:a.displayName,location:a.location,verifiedAt:now};S.registrationUsers.push(user);S.welcomePreviews=S.welcomePreviews||[];S.welcomePreviews.push({mobile:user.mobile,text:'Welcome to FreeDME, '+user.displayName+'! Your mobile is verified. You can now donate or request free equipment.',status:'simulated — not sent'});}c.used=true;S.role=a.role;S.signed=true;S.registrationProfile=user;const result={...a,created};S.access=null;save();return result;}
function finishRegistration(code){const result=verifyRegistration(code);go(result.role==='donor'?'donate':'item/'+result.item);if(result.role==='recipient'){const i=item(result.item);expire();if(!i||i.hold||i.status!=='available'||allocation(i.id)){modal('<h2>This item is no longer available</h2><p>Your sample account is ready. Browse other equipment.</p>'+link('Find equipment','browse'));}else requestDialog(result.item);}toast(result.created?'Sample registration complete. Welcome message simulated; no text sent.':'Signed in. Continue where you left off.');}

let signRole='recipient',otpTries=0;
function signin(role){S.access=null;S.registrationProfile=null;signRole=role||'recipient';otpTries=0;modal(`<h2>Try ${e(PEOPLE[signRole].role.toLowerCase())} access</h2>${signRole==='moderator'?'<p>Production staff access requires verified email, password and MFA. This design uses a fictional staff session only.</p>'+btn('Enter sample staff workspace','staff','','primary'):`<p>No real number or message is used. Your sample mobile is <b>(510) 555-0100</b>.</p><p>Ordinary users access the account with a phone code, without an email or password.</p>${btn('Send sample code','sendcode','','primary')}`}<p><small>Do not enter real credentials or personal information.</small></p>`);}
function sendcode(){modal(`<h2>Enter your sample code</h2><p>For this prototype, use <code>123456</code>. No SMS was sent.</p><form id="otp"><label>Six-digit code<input name="code" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" required autocomplete="off"></label><p id="otp-error" class="error-text" role="alert"></p><button class="primary">Continue</button></form><small>Three wrong codes invalidate this challenge. Recovery and rate-limit policies remain open.</small>`);}
function extractEvidence(){
 const f=document.getElementById('request-form'),type=f.elements.document.value,out=document.getElementById('evidence-preview');
 f.dataset.evidence='';
 if(['blurred','failure'].includes(type)){out.innerHTML='<p role="alert">'+(type==='blurred'?'The first name, last name, address and ZIP must all be readable. Choose another sample image and retry.':'Processing failed. No request was submitted. Retry with a sample document.')+'</p>';return;}
 f.dataset.evidence=type;
 out.innerHTML='<h4>Extracted details — fictional</h4><p>First name: Maya<br>Last name: Example<br>Address: 100 Example Lane, Sample City<br>ZIP code: 00000 (sample only)</p><p>Extraction complete. Backend verification passed — simulated, not real identity verification. Review the disclosure and submit to send this verified request to the donor. These fictional fields will be saved with the request in this browser.</p>';
}
function requesterEvidenceView(r){
 if(!S.signed||S.role!=='donor'||!['pending','offered','reserved','loaned'].includes(r.state)||!r.consent||r.paused||item(r.item)?.hold||S.evidence!=='reviewed')return '';
 const x=r.identityEvidence;
 return x?`<section class="note"><h3>${r.caregiver?'Caregiver':'Recipient'} identity & address</h3><p><b>Verified against sample evidence — simulation only</b></p><p>First name: ${e(x.firstName)}<br>Last name: ${e(x.lastName)}<br>Address: ${e(x.address)}<br>ZIP code: ${e(x.zip)}</p><p>${r.caregiver?'These are the caregiver’s own details. ':''}Document image is not shared. Not proof of equipment suitability or trustworthiness.</p></section>`:'<p class="note">Legacy sample request: identity and address evidence was not collected.</p>';
}
function requestDialog(id){
 const i=item(id);if(!S.signed||S.role!=='recipient'){modal(accessForm('recipient',id));return;}
 if(!i||i.status!=='available'||i.hold||allocation(id))throw Error('This item is no longer available.');
 modal(`<h2>Request ${e(i.title)}</h2><p>Next, provide your identity and address evidence. If you are requesting as a caregiver, provide your own evidence.</p><p>Your request is sent to the donor only after verification succeeds and you confirm submission. The donor will then see your reviewed first name, last name, address and ZIP code and can approve or decline.</p><p>This step does not reserve or hold the item.</p>${btn('Continue to identity verification','begin-evidence',i.id,'primary')}`);
}
function evidenceDialog(id){const i=item(id);if(i?.kind==='loan'&&i.loanUntil)i.max=loanDaysUntil(i.loanUntil);if(!S.signed||S.role!=='recipient'){modal(accessForm('recipient',id));return;}modal(`<h2>Verify identity for your request</h2><p>${e(i.title)}</p><p>You selected Request this item. Your request has not been sent to the donor. Complete identity and address verification first; failed verification will not create a pending donor request.</p><form id="request-form" data-id="${i.id}"><label>I’m requesting for<select name="for"><option value="self">Myself</option><option value="caregiver">Someone I’m helping</option></select></label>${i.kind==='loan'?`<label>Loan length in days<input type="number" name="days" min="1" max="${i.max}" value="${i.max}" required></label>`:''}<section class="note"><h3>Identity and address evidence</h3><p>Required for free gifts and loans. Upload an image of a utility bill OR driver’s license showing your first name, last name, address and ZIP code clearly. If you are a caregiver, provide your own evidence, not the care recipient’s.</p><p><b>Design simulation only:</b> choose a fictional image below. No real file is uploaded, no OCR service runs, and no backend database is connected.</p><label>Sample document image<select name="document"><option value="utility">Fictional utility bill</option><option value="license">Fictional driver’s license</option><option value="blurred">Unreadable image / missing ZIP</option><option value="failure">Simulate processing failure</option></select></label>${btn('Simulate upload & extract details','extract-evidence')}<div id="evidence-preview" aria-live="polite"></div></section>${check('disclose',`I consent to share my reviewed first name, last name, address and ZIP code with <b>${e(i.owner)}</b> for this request for <b>${e(i.title)}</b>. If I am a caregiver, these are my own details. The document image is not shared.`)}${guidance}${check('ack','I understand pickup is my responsibility and have read the equipment and safety guidance (preview v0.9).')}${check('authority','If helping someone else, I have authority to act for them and understand whose information would be disclosed.') }<p class="error-text" id="request-error" role="alert"></p><button class="primary">Send verified request to donor</button></form>`);}
function reviewDialog(id){const i=item(id);modal(`<h2>Review ${e(i.title)}</h2><p>${e(i.defects)} Model: ${e(i.model)}.</p><form id="review" data-id="${id}">${check('disclosures','I reviewed the sample disclosures, photos and category configuration.') }<label>Recall screening result<select name="recall" required><option value="">Select outcome</option><option value="no_match">No match found (sample)</option><option value="potential">Potential match</option><option value="confirmed">Confirmed unresolved recall</option><option value="insufficient">Insufficient identification</option></select></label><label>Review source<input name="source" required placeholder="Sample FDA / CPSC / manufacturer review"></label><label>Decision reason<textarea name="reason" required placeholder="Explain the outcome to the donor"></textarea></label><label>Decision<select name="decision"><option value="available">Approve for publication</option><option value="pending_review">Request corrections</option><option value="rejected">Reject</option></select></label>${i.hold?check('resolved','The sample identification / safety hold has been resolved through documented review.',false):''}<p class="error-text" id="review-error" role="alert"></p><button class="primary">Record review</button><p><small>Sample screening only, not a recall check or equipment certification.</small></p></form>`);}
function reportDialog(id){modal(`<h2>Tell us about a concern</h2><p>This sample report goes only to the simulated staff queue. Do not include real personal or medical details.</p><form id="report" data-id="${id||0}"><label>Reason<select name="reason">${['Unsafe equipment','Suspected recall','Payment demand','Harassment','Privacy misuse','Failed pickup','Non-return','Transport barrier','Help using the website'].map(x=>`<option>${x}</option>`).join('')}</select></label><label>What happened?<textarea name="detail" required maxlength="500" placeholder="Use a fictional example"></textarea></label><button class="primary">Submit sample report</button></form><div class="note warn">FreeDME is not an emergency service. No real support staff receive this form.</div>`);}
function action(a,id){try{if(a==='recipient-tab'){selectRecipientTab(id);return;}if(a==='donor-tab'){selectDonorTab(id);return;}if(a==='ask-question'){questionDialog(id);return;}if(a==='answer-question'){answerDialog(id);return;}if(a==='registration-signout'){S.signed=false;S.role='visitor';S.registrationProfile=null;S.access=null;save();go('home');}else if(a==='welcome-preview'){modal('<h2>Welcome message preview</h2><p>'+e(S.welcomePreviews?.at(-1)?.text||'No new registration yet.')+'</p><p>Simulated only. No SMS was sent.</p>');}else if(a==='registration-resend')startRegistrationCode();else if(a==='retryrequest'){try{requestDialog(retryItem(id));}catch(err){modal('<h2>Request again</h2><p>'+e(err.message)+'</p>'+link('Find available equipment','browse'));}}else if(a==='removerequest'){removeExpiredRequest(id);render();toast('Expired request removed from your list. Use Restore removed requests to undo.');}else if(a==='restorerequests'){restoreExpiredRequests();render();}else if(a==='detailphoto')detailPhoto(id);else if(a==='rotate')rotatePhoto(id);else if(a==='photo')showPhoto(id);else if(a==='close')close();else if(a==='lab')lab();else if(a==='signin')signin(id);else if(a==='sendcode')sendcode();else if(a==='staff'){S.role='moderator';S.signed=true;save();go('activity');}else if(a==='browse')go('browse');else if(a==='donate')go('donate');else if(a==='edit')go('donate/'+id);else if(a==='detail')go('item/'+id);else if(a==='category'){filters.cat=id;render(false);}else if(a==='resetfilters'){filters={q:'',cat:'All equipment',city:'All locations',kind:'All'};render();}else if(a==='request')requestDialog(id);else if(a==='review'){if(S.role!=='moderator')throw Error('Use the sample moderator role.');reviewDialog(id);}else if(a==='report'||a==='help')reportDialog(id);else if(a==='guidance')modal('<h2>Plan a safe handoff</h2>'+guidance+'<p>Timing and location are arranged directly by participants. Conversational SMS privacy rules are unresolved (DEC05), so this prototype does not send messages or provide an in-account chat.</p>');else if(a==='handoff-propose'){handoffDialog(id);}else if(a==='handoff-agree'){const [rid,revision]=id.split(':');updateHandoff(rid,revision,{},true);render();toast('Handoff arrangements accepted. Physical handoff is not yet confirmed.');}else if(a==='begin-evidence'){evidenceDialog(id);}else if(a==='extract-evidence'){extractEvidence();}else if(a==='offer'){approveDialog(id);}else if(['decline','unavailable','handoff','return'].includes(a)){move(id,a);render();toast(a==='offer'?'Offer made. Waiting for recipient acceptance; not reserved yet.':'Sample action recorded: '+a);}else if(a==='accept'){modal(`<h2>Accept this offer?</h2>${guidance}<form id="accept" data-id="${id}">${check('safety','I acknowledge the pickup responsibility and equipment guidance.')}<button class="primary">Accept & reserve</button><p class="error-text" id="accept-error" role="alert"></p></form>`);}else if(a==='cancel'){modal(`<h2>Cancel your request</h2><form id="cancel" data-id="${id}"><label>Reason<select name="reason"><option>Plans changed</option><option>Transport barrier</option><option>Item unsuitable</option><option>Safety concern</option></select></label><p>The item will not automatically reopen. The donor must confirm possession and availability.</p><button class="primary">Confirm cancellation</button></form>`);}else if(a==='reopen')modal(`<h2>Make this item available again</h2><form id="reopen" data-id="${id}">${check('possession','I confirm I actually have this item, it is available, and the prior exchange has ended.')}<p>Safety holds block reopening. Prior action links will be invalidated.</p><p id="reopen-error" class="error-text" role="alert"></p><button class="primary">Confirm & reopen</button></form>`);else if(a==='withdraw'){const i=item(id);if(S.role!=='donor')throw Error('Owner access required.');modal(`<h2>Withdraw ${e(i.title)}?</h2><p>Pending requests and offers will close. Any handoff or loan-return obligation remains separate.</p>${btn('Confirm withdrawal','confirmwithdraw',id,'primary')}`);}else if(a==='confirmwithdraw'){if(S.role!=='donor')throw Error('Owner access required.');const i=item(id);i.status='withdrawn';const r=allocation(id);if(r&&['pending','offered'].includes(r.state))r.state='closed_unavailable';event(i.title+' withdrawn.');save();go('activity');}else if(a==='disclosure'){const r=request(id);if(S.role!=='donor'||!r.consent||S.evidence!=='reviewed'||!active(r))throw Error('Disclosure is unavailable: current consent and evidence are required.');event('Sensitive sample disclosure viewed by named donor for '+id);save();modal('<h2>Borrower details · fictional</h2><p>Shared only for this loan request. No original evidence or document metadata is shown.</p><div class="data"><div><small>Name · reviewed against sample evidence</small>Maya Example</div><div><small>Address · reviewed against sample evidence</small>100 Example Lane, Sample City</div><div><small>Phone · sample contact verified</small>(510) 555-0100</div><div><small>Email</small>Not supplied</div></div>');}else if(a==='revoke'){revokeConsent(id);render();toast('Disclosure access removed; loan progression blocked.');}else if(a==='case'){const c=S.cases.find(x=>x.id===id);if(S.role!=='moderator')throw Error('Staff access required.');modal(`<h2>${e(c.reason)}</h2><p>${e(c.detail)}</p>${followupContext(c)}<p>Owner: ${e(c.owner)} · Severity: ${e(c.severity)} · ${e(c.state)}</p><div class="actions">${btn('Acknowledge','caseack',id)}${c.item?btn('Hide item / apply hold','hold',id):''}${btn('Close case with reason','caseclose',id)}</div><p>Closing a case does not release a safety hold or reopen an item.</p>`);}else if(['caseack','hold','caseclose'].includes(a)){if(S.role!=='moderator')throw Error('Staff access required.');const c=S.cases.find(x=>x.id===id);if(a==='caseclose'){modal(`<h2>Close ${e(id)}</h2><form id="caseclose" data-id="${id}"><label>Closure reason<textarea name="reason" required></textarea></label><button class="primary">Record closure</button></form>`);return;}if(a==='hold'){item(c.item).hold=true;item(c.item).status='unavailable';c.state='investigating';}else c.state='acknowledged';event(c.id+' '+c.state);save();close();render();}else if(a==='sms'){if(S.sms){S.sms=false;S.requests.filter(active).forEach(r=>r.paused='routine SMS opt-out');event('Routine SMS withdrawn; retries suppressed.');save();render();toast('Routine SMS off. Account tasks remain visible.');}else modal('<h2>Resume routine texts</h2><p>Opt-out recovery is not yet approved (DEC05). Use Reset sample data to start a new review scenario. OTP consent remains separate.</p>');}else if(a==='advance'){S.time+=+id*3600000;expire();render();lab();}else if(a==='fail'){S.requests.filter(active).forEach(r=>r.paused='delivery failure');event('Sample delivery failure; active exchanges paused.');save();render();lab();}else if(a==='badevidence'){S.evidence='revoked';S.requests.forEach(r=>r.consent=false);event('Sample evidence revoked; all associated grants invalidated.');save();render();lab();}else if(a==='reset'){modal(`<h2>Reset this review session?</h2><p>This clears only this prototype’s fictional listings, requests and cases.</p>${btn('Reset sample data','confirmreset','','primary')}`);}else if(a==='confirmreset'){S=SEED();save();go('home');toast('Sample data reset.');}else if(a==='share'){const url=location.href.split('#')[0]+'#item/'+id;if(navigator.clipboard)navigator.clipboard.writeText(url).then(()=>toast('Public sample listing link copied.')).catch(()=>modal('<h2>Copy this sample link</h2><textarea readonly>'+e(url)+'</textarea>'));else modal('<h2>Copy this sample link</h2><textarea readonly>'+e(url)+'</textarea>');}else if(a==='filldonor'){const f=document.getElementById('donate-form');f.elements.namedItem('title').value='Folding walker for a neighbor';f.elements.namedItem('desc').value='Fictional folding walker, offered as a free gift. Please confirm condition and suitability in person.';f.elements.namedItem('model').value='Sample W-100';}}
catch(err){toast(err.message);}}
function submit(ev){const f=ev.target;if(!f.id)return;ev.preventDefault();const d=new FormData(f);try{if(f.id==='handoff-proposal'){const r=updateHandoff(f.dataset.id,f.dataset.revision,Object.fromEntries(d));close();render();toast('Suggestion saved. '+r.handoffNotifications.at(-1).status);}else if(f.id==='approve-request'){const r=approveWithSuggestion(f.dataset.id,Object.fromEntries(d));close();render();toast('Approved. '+r.approvalNotification);}else if(f.id==='question-answer'){const q=answerQuestion(f.dataset.question,d.get('answer'));close();render();toast('Answer saved. '+q.answerNotification);}else if(f.id==='item-question'){const q=addQuestion(f.dataset.item,d.get('question'));render();modal('<h2>Question submitted</h2><p>Your question is saved in the donor’s pending questions.</p><p>'+e(q.notification)+'</p><p>This does not reserve the item.</p>');}else if(f.id==='access-mobile'){const existing=beginAccess(f.dataset.role,f.dataset.item,d.get('mobile'));if(existing)startRegistrationCode();else go('register');}else if(f.id==='registration-form'){prepareRegistration(Object.fromEntries(d));startRegistrationCode();}else if(f.id==='registration-otp'){finishRegistration(d.get('code'));}else if(f.id==='otp'){S.registrationProfile=null;if(d.get('code')!=='123456'){otpTries++;if(otpTries>=3){modal('<h2>Sample challenge invalidated</h2><p>Three wrong codes were entered. No account is suspended. Production cooldown and abuse limits require approval.</p>'+btn('Return to review controls','lab'));return;}document.getElementById('otp-error').textContent='That code did not match. '+(3-otpTries)+' sample attempts remain.';return;}S.role=signRole;S.signed=true;save();go('activity');toast('Signed in to the fictional '+PEOPLE[S.role].role+' account.');}else if(f.id==='request-form'){if(f.dataset.evidence!==d.get('document'))throw Error('Simulate upload and extraction for the selected document first.');S.evidence='reviewed';createRequest(f.dataset.id,{evidenceDocument:f.dataset.evidence,loanDays:d.get('days'),caregiver:d.get('for')==='caregiver',consent:!!d.get('disclose')});go('activity');toast('Request submitted. The donor has up to 48 hours to respond.');}else if(f.id==='accept'){move(f.dataset.id,'accept');go('activity');toast('Reserved. Physical handoff is not yet confirmed.');}else if(f.id==='cancel'){const r=request(f.dataset.id);move(r.id,'cancel');if(d.get('reason')==='Transport barrier')report(r.item,'Transport barrier','Fictional cancellation: transport unavailable.');go('activity');}else if(f.id==='reopen'){reopen(f.dataset.id,!!d.get('possession'));go('activity');}else if(f.id==='donate-form'){if(!f.dataset.edit&&!d.get('noDefects'))throw Error('Confirm there are no known missing parts.');if(!String(d.get('city')||'').trim())throw Error('Enter a ZIP code or town name.');if(S.role!=='donor'||!S.signed)throw Error('Donor sign-in required.');if(d.getAll('photos').length<1||d.getAll('photos').length>5)throw Error('Select between one and five sample photos.');const publicText=['title','desc','model','defects','mods','pickup'].map(k=>d.get(k)).join(' ');if(/@|https?:|\b\d{3}[- .]\d{3}[- .]\d{4}\b|\b\d+\s+\w+\s+(street|lane|road|avenue|drive)\b/i.test(publicText))throw Error('Remove private contact or street-address details from public fields.');const old=item(f.dataset.edit);if(old&&allocation(old.id))throw Error('Close the active allocation before material edits.');const i={id:old?.id||Math.max(...S.items.map(x=>x.id))+1,title:d.get('title'),cat:d.get('cat'),city:d.get('city').trim(),miles:4,kind:d.get('kind'),status:'pending_review',owner:'Jordan',condition:d.get('condition'),model:d.get('model'),desc:d.get('desc'),clean:d.get('clean'),defects:(old?d.get('defects'):'No known missing parts — donor confirmed.')+' Modifications: '+d.get('mods'),loanUntil:d.get('kind')==='loan'?d.get('loanUntil'):null,max:d.get('kind')==='loan'?loanDaysUntil(d.get('loanUntil')):0,hold:old?.hold||false};if(i.kind==='loan'&&(!Number.isInteger(i.max)||i.max<1))throw Error('Loan maximum must be a positive whole number of days.');if(old)Object.assign(old,i);else S.items.push(i);event(i.title+' submitted for screening; donor agreement preview v0.9 acknowledged.');save();go('activity');toast('Submitted for moderator review. Not publicly visible.');}else if(f.id==='review'){if(S.role!=='moderator')throw Error('Staff role required.');const i=item(f.dataset.id);if(d.get('decision')==='available'&&(d.get('recall')!=='no_match'||(i.hold&&!d.get('resolved'))))throw Error('Unresolved recalls, uncertain identification or safety holds block publication.');i.status=d.get('decision');if(i.status==='available')i.hold=false;else if(['potential','confirmed','insufficient'].includes(d.get('recall')))i.hold=true;event('Alex reviewed '+i.title+': '+i.status+'; recall '+d.get('recall')+'; source '+d.get('source')+'; reason '+d.get('reason'));save();go('activity');toast('Sample screening outcome recorded.');}else if(f.id==='report'){const c=report(f.dataset.id,d.get('reason'),d.get('detail'));modal('<h2>Sample report received</h2><p>Reference '+e(c.id)+'. Assigned to Alex in the simulated moderator queue.</p><p>No real report was sent. Actual support hours and response times await approval.</p>');}else if(f.id==='caseclose'){if(S.role!=='moderator')throw Error('Staff role required.');const c=S.cases.find(x=>x.id===f.dataset.id);c.state='closed';c.closure=d.get('reason');event(c.id+' closed: '+c.closure);save();go('activity');}}
catch(err){const target=f.querySelector('[role=alert]');if(target)target.textContent=err.message;else toast(err.message);}}
if(typeof document!=='undefined'){
 try{const stored=JSON.parse(localStorage.getItem('freedme-review-v09'));if(stored?.version===1&&Array.isArray(stored.items))S=stored;}catch(_){}
 for(const sample of SEED().items){const existing=item(sample.id);if(sample.loanUntil&&existing?.kind==='loan'&&existing.model===sample.model&&!existing.loanUntil)existing.loanUntil=sample.loanUntil;}
 document.addEventListener('click',ev=>{const b=ev.target.closest('[data-action]');if(b){ev.preventDefault();action(b.dataset.action,b.dataset.id);}if(ev.target.closest('dialog a'))close();});
let swipeStart=null;
 document.addEventListener('pointerdown',ev=>{const area=ev.target.closest('.swipe-area');if(!area||!ev.isPrimary||ev.button!==0)return;swipeStart={id:ev.pointerId,x:ev.clientX,y:ev.clientY,area};area.setPointerCapture(ev.pointerId);});
 document.addEventListener('pointerup',ev=>{if(!swipeStart||ev.pointerId!==swipeStart.id)return;const dx=ev.clientX-swipeStart.x,dy=ev.clientY-swipeStart.y;const area=swipeStart.area;swipeStart=null;if(area.isConnected&&Math.abs(dx)>45&&Math.abs(dx)>Math.abs(dy)*1.4)rotatePhoto(dx<0?1:-1);});
 document.addEventListener('pointercancel',()=>{swipeStart=null;});
 document.addEventListener('keydown',ev=>{if(ev.target.matches('.recipient-tabs [role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();const keys=Object.keys(recipientTabLabels),n=keys.indexOf(ev.target.dataset.id);selectRecipientTab(keys[ev.key==='Home'?0:ev.key==='End'?keys.length-1:(n+(ev.key==='ArrowRight'?1:-1)+keys.length)%keys.length]);return;}if(ev.target.matches('.donor-tabs [role=tab]')&&['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();const keys=Object.keys(donorTabLabels),n=keys.indexOf(ev.target.dataset.id);selectDonorTab(keys[ev.key==='Home'?0:ev.key==='End'?keys.length-1:(n+(ev.key==='ArrowRight'?1:-1)+keys.length)%keys.length]);return;}if(ev.target.matches('.swipe-area')&&['ArrowLeft','ArrowRight','Home','End'].includes(ev.key)){ev.preventDefault();if(ev.key==='Home')detailPhoto(0);else if(ev.key==='End')detailPhoto(VIEW_NAMES.length-1);else rotatePhoto(ev.key==='ArrowRight'?1:-1);}});
 document.addEventListener('submit',submit);document.addEventListener('change',ev=>{if(ev.target.matches('#donate-form select[name=kind]')){const input=ev.target.form.elements.namedItem('loanUntil');input.disabled=ev.target.value!=='loan';input.required=ev.target.value==='loan';}if(['city','kind'].includes(ev.target.id)){filters[ev.target.id]=ev.target.value;render(false);}});document.addEventListener('input',ev=>{if(ev.target.id==='search'){const caret=ev.target.selectionStart;filters.q=ev.target.value;render(false);const el=document.getElementById('search');el.focus();el.setSelectionRange(caret,caret);}});window.addEventListener('hashchange',()=>render());render(false);
}
if(typeof module!=='undefined')module.exports={requesterEvidenceView,updateHandoff,handoffSuggestionView,approveWithSuggestion,seed:SEED,get:()=>S,set:s=>S=s,createRequest,move,reopen,report,expire,detail,activity,revokeConsent,moderator,followupContext,retryItem,removeExpiredRequest,restoreExpiredRequests,loanDaysUntil,donate,normalizeMobile,beginAccess,prepareRegistration,verifyRegistration,registrationPage,addQuestion,donorQuestions,answerQuestion,recipientQuestions};
